import password_store

def register_password(password: str) -> str:
    """
    Hash a new password according to the organisation's current password-storage policy.
    Returns the encoded hash string to store.
    """
    return password_store.hash_new_password(password)

def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt password against a stored password hash.
    Supports all legacy and current formats.
    Returns True if the password matches, False otherwise.
    """
    try:
        return password_store.verify_password(password, stored)
    except ValueError:
        # Malformed or unknown hash format means verification fails
        return False
